package com.project.kafka.StreamPackage;

import java.util.Properties;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.KafkaStreams;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.kstream.Predicate;

public class FilterStream {
    public static void main(final String[] args) throws Exception {

        // 1. Configuration
        Properties clickStreamConfig = new Properties();
        clickStreamConfig.put(StreamsConfig.APPLICATION_ID_CONFIG, "ClickStreamAnalysis");
        clickStreamConfig.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        clickStreamConfig.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        clickStreamConfig.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());

        // 2. Build Stream Topology
        StreamsBuilder builder = new StreamsBuilder();

        // 3. Read Stream from Topic
        KStream<String, String> streamData = builder.stream(args[0]); // e.g. YouBuyyClickStreamData

        // 4. Filter records with SessionTime > 30 seconds
        KStream<String, String> filteredRecords = streamData.filter(
            new Predicate<String, String>() {
                public boolean test(String key, String value) {
                    String[] fields = value.split(",");
                    int sessionTime = Integer.parseInt(fields[4]); // Assuming 5th field is session time
                    return sessionTime > 30;
                }
            }
        );

        // 5. Write filtered records to new topic
        filteredRecords.to(args[1]); // e.g. CleansedYouBuyyClickStreamData

        // 6. Start the Stream
        KafkaStreams streams = new KafkaStreams(builder.build(), clickStreamConfig);
        streams.start();

        System.out.println("Cleansing the records is complete.");
    }
}

String[] fields = value.split(",");
int hoursWorked = calculateTimeInMinutes(fields[1], fields[3]); // e.g. 8:30 AM to 12:00 PM
return hoursWorked < 210;

